mapper.sql:
t.tenant_id = #{tenantId} AND t.factory_code = #{q.factoryCode} AND t.del_flag = '0'
AND t.code = #{q.taskCode}
AND t.workshop_code = #{q.workshopCode}
AND t.mat_code = #{q.materialCode}

    AND ((t.plan_start_date < #{end} AND t.plan_end_date > #{start})
        OR (t.start_time < #{end} AND (t.finish_time IS NULL OR t.finish_time > #{start})))


    AND EXISTS (SELECT 1 FROM mes_task_arrange a WHERE a.tenant_id=t.tenant_id
        AND a.factory_code=t.factory_code AND a.task_code=t.code AND a.del_flag='0'
        AND a.shift_code=#{q.shiftCode})

r.tenant_id=#{tenantId} AND r.factory_code=#{q.factoryCode} AND r.del_flag='0'
AND r.report_time >= #{start} AND r.report_time < #{end}
AND r.task_code=#{q.taskCode}
AND r.mat_code=#{q.materialCode}
AND r.report_unit=#{q.reportUnit}

mapper.select:
SELECT grouped.*, COUNT(*) OVER () AS population_count FROM (
SELECT COALESCE(NULLIF(t.workshop_code,''),'UNKNOWN')t.code AS group_code, COUNT(*) AS metric_value FROM mes_task t WHERE GROUP BY COALESCE(NULLIF(t.workshop_code,''),'UNKNOWN')t.code
SELECT COALESCE(NULLIF(a.workshop_code,''),'UNKNOWN') COALESCE(NULLIF(a.shift_code,''),'UNKNOWN')COALESCE(NULLIF(r.task_code,''),'UNKNOWN') AS group_code, CASE WHEN COUNT(*) FILTER (WHERE COALESCE(r.effective_report_num,r.report_num) IS NULL OR COALESCE(r.effective_report_num,r.report_num)<0)=0 THEN SUM(COALESCE(r.effective_report_num,r.report_num)) END CASE WHEN COUNT(*) FILTER (WHERE r.quality_rejected_num IS NULL OR r.quality_rejected_num<0)=0 THEN SUM(r.quality_rejected_num) ENDCOUNT(*) AS metric_value WHERE AND GROUP BY COALESCE(NULLIF(a.workshop_code,''),'UNKNOWN') COALESCE(NULLIF(a.shift_code,''),'UNKNOWN')COALESCE(NULLIF(r.task_code,''),'UNKNOWN')
) grouped ORDER BY metric_value ASCDESC NULLS LAST, group_code ASC LIMIT #{q.rankLimit}
